// Pure helpers for the monitor: reduce platform runs to what the page shows, group them into builds (one per uploaded
// package) and judge the latest build against the one before. No network here, so `node --test` covers it.

const FINAL = ["submitted", "scored", "failed", "timed_out"];
const DEAD = ["cancelled", "canceled"];
const TOP = ["decision", "tender_reference", "discount_percent", "total_net", "total_consistency", "withdrawn_answer",
  "index_window"];
const FIELDS = ["material_number", "quantity", "base_unit_price", "surcharge_per_unit", "packaging_per_unit",
  "rebate_total", "unit_price", "lead_time_weeks"];
const SAME = 0.05; // relative difference below which two builds count as the same
const SAME_QUALITY = 5; // the same, in quality points

// Points per answer field, summed over the positions. The values the platform echoes ("got") are left behind.
function fieldPoints(breakdown) {
  if (!breakdown) return null;
  const points = {};
  for (const key of TOP) if (breakdown[key]) points[key] = breakdown[key].points ?? 0;
  const positions = breakdown.positions || [];
  for (const field of FIELDS) {
    points[field] = Math.round(positions.reduce((sum, position) => sum + ((position[field] || {}).points || 0), 0) * 100) / 100;
  }
  return points;
}

function slim(run) {
  const score = run.score || {};
  const started = run.started_at, finished = run.finished_at;
  const ms = score.duration_ms || (started && finished ? finished - started : null);
  return {
    id: run.run_id,
    status: run.status,
    created: run.created_at || started || 0,
    started: started || null,
    expires: run.expires_at || null,
    seconds: ms ? Math.round(ms / 100) / 10 : null,
    quality: score.quality ?? null,
    eligible: score.eligible ?? null,
    cost: (run.cost_micro_usd || 0) / 1e6,
    calls: run.calls || 0,
    tokens: (run.input_tokens || 0) + (run.output_tokens || 0),
    failure: run.failure_class || null,
    pkg: ((run.package || {}).sha256 || "unknown").slice(0, 12),
    label: (run.package || {}).label || null,
    points: fieldPoints(score.breakdown),
  };
}

function median(values) {
  const sorted = values.filter((value) => value != null).sort((a, b) => a - b);
  if (!sorted.length) return null;
  const mid = sorted.length >> 1;
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

// The platform's tie-breaker, with its floors of $0.01 and 1 s.
const costTime = (run) => Math.max(run.cost, 0.01) * Math.max(run.seconds, 1);

function buildStats(runs) {
  const done = runs.filter((run) => FINAL.includes(run.status));
  const answered = done.filter((run) => run.quality != null && run.seconds);
  // a finished run without a score entered no answer, which is worth 0
  const qualities = done.map((run) => run.quality ?? 0);
  return {
    runs: runs.length,
    done: done.length,
    running: runs.filter((run) => !FINAL.includes(run.status)).length,
    full: qualities.filter((quality) => quality >= 100).length,
    quality: qualities.length ? Math.round(qualities.reduce((a, b) => a + b, 0) / qualities.length * 10) / 10 : null,
    progression: qualities,
    seconds: median(answered.map((run) => run.seconds)),
    cost: median(answered.map((run) => run.cost)),
    costTime: median(answered.map(costTime)),
  };
}

function groupBuilds(runs) {
  const builds = new Map();
  for (const run of [...runs].sort((a, b) => a.created - b.created)) {
    if (!builds.has(run.pkg)) builds.set(run.pkg, { n: builds.size + 1, pkg: run.pkg, label: run.label, first: run.created, runs: [] });
    builds.get(run.pkg).runs.push(run);
  }
  return [...builds.values()].map((build) => ({ ...build, ...buildStats(build.runs) }));
}

// 1 better, -1 worse, 0 the same; `lower` says a smaller number is the better one.
function direction(now, before, lower) {
  if (now == null || before == null) return null;
  const same = lower ? Math.abs(now - before) < SAME * Math.max(before, 1e-9) : Math.abs(now - before) < SAME_QUALITY;
  if (same) return 0;
  return (now < before) === Boolean(lower) ? 1 : -1;
}

function compare(build, before) {
  return {
    quality: direction(build.quality, before.quality, false),
    seconds: direction(build.seconds, before.seconds, true),
    cost: direction(build.cost, before.cost, true),
    costTime: direction(build.costTime, before.costTime, true),
  };
}

// The latest build with at least two finished runs against the one before it: quality decides, then cost x time.
function verdict(builds) {
  const judged = builds.filter((build) => build.done >= 2);
  const latest = judged[judged.length - 1], before = judged[judged.length - 2];
  const newest = builds[builds.length - 1];
  const waiting = newest && newest !== latest ? newest.n : null;
  if (!latest || !before) return { result: null, waiting };
  const delta = compare(latest, before);
  const result = delta.quality || delta.costTime || 0;
  return { result, by: delta.quality ? "quality" : result ? "cost × time" : null, latest: latest.n, before: before.n, waiting };
}

function state(platformRuns, now) {
  const runs = platformRuns.filter((run) => run.kind === "rehearsal" && !DEAD.includes(run.status)).map(slim);
  const builds = groupBuilds(runs);
  builds.forEach((build, index) => { build.delta = index ? compare(build, builds[index - 1]) : {}; });
  return {
    updated: now,
    verdict: verdict(builds),
    running: runs.filter((run) => !FINAL.includes(run.status)).sort((a, b) => b.created - a.created)
      .map((run) => ({ ...run, build: builds.find((build) => build.pkg === run.pkg).n })),
    builds: builds.reverse(),
  };
}

module.exports = { FINAL, fieldPoints, slim, median, buildStats, groupBuilds, direction, verdict, state };

// GET /api/runs: the team's test runs grouped into builds, read from the platform with the ATIRA_TOKEN secret.
// Only run numbers and points per field leave this function, never the token or the answer values.

const { state } = require("./_lib.js");

const API = "https://ehl-challenge.atira.ai";
const FRESH_MS = 10_000; // every viewer within this window shares one platform request
let cache = null;

module.exports = async (request, response) => {
  response.setHeader("Cache-Control", "public, s-maxage=5, stale-while-revalidate=10");
  const now = Date.now();
  if (cache && now - cache.updated < FRESH_MS) return response.status(200).json(cache);
  const token = process.env.ATIRA_TOKEN;
  if (!token) return response.status(500).json({ error: "ATIRA_TOKEN is not set on this deployment" });
  try {
    const answer = await fetch(`${API}/v1/runs`, {
      headers: { "x-api-key": token, "User-Agent": "error404ai-monitor/1.0" },
      signal: AbortSignal.timeout(20_000),
    });
    if (!answer.ok) throw new Error(`platform answered ${answer.status}`);
    cache = state((await answer.json()).runs || [], now);
    return response.status(200).json(cache);
  } catch (error) {
    if (cache) return response.status(200).json({ ...cache, stale: String(error.message || error) });
    return response.status(502).json({ error: String(error.message || error) });
  }
};

// node --test monitor/api/_lib.test.js   (invented runs, no network)
const test = require("node:test");
const assert = require("node:assert");
const { state, slim, direction } = require("./_lib.js");

let clock = 1_000_000;
function run(pkg, quality, seconds = 400, cost = 0.1, extra = {}) {
  clock += 60_000;
  return {
    run_id: `run_${clock}`, kind: "rehearsal", status: "submitted", created_at: clock, started_at: clock,
    finished_at: clock + seconds * 1000, cost_micro_usd: cost * 1e6, calls: 100, package: { sha256: pkg.repeat(64) },
    score: quality == null ? null : {
      quality, eligible: true, duration_ms: seconds * 1000,
      breakdown: { decision: { got: "placeholder", points: 5 }, positions: [{ quantity: { got: 7, points: 1.5 } }, { quantity: { got: 9, points: 1.5 } }] },
    },
    ...extra,
  };
}

test("only test runs are kept, and no answer value survives", () => {
  const page = state([run("a", 100), run("a", 100, 400, 0.1, { kind: "scored" })], 0);
  assert.equal(page.builds[0].runs.length, 1);
  assert.ok(!JSON.stringify(page).includes("placeholder"));
  assert.equal(page.builds[0].runs[0].points.quantity, 3);
});

test("builds are numbered by first appearance, newest first", () => {
  const page = state([run("a", 100), run("b", 100), run("a", 100)], 0);
  assert.deepEqual(page.builds.map((build) => [build.n, build.runs.length]), [[2, 1], [1, 2]]);
});

test("a run that finished without a score counts as quality 0", () => {
  const page = state([run("a", 100), run("a", null, 5, 0, { status: "failed" })], 0);
  assert.equal(page.builds[0].quality, 50);
  assert.deepEqual(page.builds[0].progression, [100, 0]);
  assert.equal(page.builds[0].seconds, 400);
});

test("quality decides the verdict before cost and time", () => {
  const page = state([run("a", 100), run("a", 100), run("b", 100, 100, 0.01), run("b", 5, 100, 0.01)], 0);
  assert.deepEqual([page.verdict.result, page.verdict.by, page.verdict.latest, page.verdict.before], [-1, "quality", 2, 1]);
});

test("equal quality falls back to cost x time, and small differences are the same", () => {
  const faster = state([run("a", 100, 600), run("a", 100, 600), run("b", 100, 300), run("b", 100, 300)], 0);
  assert.deepEqual([faster.verdict.result, faster.verdict.by], [1, "cost × time"]);
  const same = state([run("a", 100, 600), run("a", 100, 600), run("b", 100, 590), run("b", 100, 590)], 0);
  assert.equal(same.verdict.result, 0);
});

test("a build with one finished run is not judged yet", () => {
  const page = state([run("a", 100), run("a", 100), run("b", 100), run("b", 100), run("c", 5)], 0);
  assert.deepEqual([page.verdict.latest, page.verdict.before, page.verdict.waiting], [2, 1, 3]);
});

test("runs in flight are listed with their build and no duration", () => {
  const page = state([run("a", 100), run("b", null, 0, 0.02, { status: "running", finished_at: null })], 0);
  assert.deepEqual([page.running.length, page.running[0].build, page.running[0].seconds], [1, 2, null]);
  assert.equal(page.builds[0].done, 0);
});

test("direction: lower is better for time and cost", () => {
  assert.deepEqual([direction(90, 100, true), direction(110, 100, true), direction(98, 100, true), direction(null, 1, true)], [1, -1, 0, null]);
  assert.equal(slim(run("a", 100)).pkg.length, 12);
});

// Local preview without the Vercel CLI: ATIRA_TOKEN=$(atira token) node monitor/dev-server.js [port]
const http = require("node:http");
const fs = require("node:fs");
const path = require("node:path");
const runs = require("./api/runs.js");

const port = Number(process.argv[2]) || 3000;
http.createServer((request, response) => {
  if (request.url.startsWith("/api/runs")) {
    response.status = (code) => { response.statusCode = code; return response; };
    response.json = (body) => { response.setHeader("Content-Type", "application/json"); response.end(JSON.stringify(body)); };
    return runs(request, response);
  }
  response.setHeader("Content-Type", "text/html; charset=utf-8");
  response.end(fs.readFileSync(path.join(__dirname, "index.html")));
}).listen(port, "127.0.0.1", () => console.log(`http://127.0.0.1:${port}`));

